type IsoDate = string & { readonly __brand: "IsoDate" };
type Effectivity = { from: IsoDate; until: IsoDate | null };   // null = until further notice

const effectiveOn = (e: Effectivity, asOf: IsoDate): boolean =>
  asOf >= e.from && (e.until === null || asOf < e.until);

