import { areIntervalsOverlapping, isWithinInterval, type Interval } from "date-fns";

interface Effectivity { readonly effective: Interval<Date, Date>; }

const effectiveOn = (e: Effectivity, asOf: Date): boolean => isWithinInterval(asOf, e.effective);
const clash = (a: Effectivity, b: Effectivity) => areIntervalsOverlapping(a.effective, b.effective);
